import{_ as i,C as r,o as l,c as d,ag as o,E as n,j as t,a}from"./chunks/framework.D1ek-kcM.js";const k=JSON.parse('{"title":"Managing App Requests","description":"","frontmatter":{},"headers":[],"relativePath":"mobile-app/managing-app-requests.md","filePath":"mobile-app/managing-app-requests.md","lastUpdated":1788933864000}'),p={name:"mobile-app/managing-app-requests.md"};function g(h,e,u,c,m,f){const s=r("ImagePopup");return l(),d("div",null,[e[0]||(e[0]=o('<h1 id="managing-app-requests" tabindex="-1">Managing App Requests <a class="header-anchor" href="#managing-app-requests" aria-label="Permalink to &quot;Managing App Requests&quot;">​</a></h1><p>Every tenant&#39;s app request arrives in one place for the super admin to review, send to the mobile team, and close out with a download link. This page covers that side of the workflow.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to review a tenant&#39;s app request</li><li>How to raise a build ticket with the mobile team</li><li>How to deliver the finished app, request a correction, or reject</li></ul></div><h2 id="viewing-requests" tabindex="-1">Viewing requests <a class="header-anchor" href="#viewing-requests" aria-label="Permalink to &quot;Viewing requests&quot;">​</a></h2><p>Go to <strong>Mobile App Requests → All Requests</strong> to see every request across all tenants, with the tenant name and domain alongside each one. You can <strong>search</strong>, <strong>filter</strong>, and <strong>paginate</strong> to find a request quickly.</p>',5)),n(s,{src:"/images/managing-app-requests/super-app-requests.png",alt:"All app requests"}),e[1]||(e[1]=t("p",null,[a("Click the "),t("strong",null,"View"),a(" (eye) icon on a row to open the full request.")],-1)),n(s,{src:"/images/managing-app-requests/super-request-detail.png",alt:"App request detail"}),e[2]||(e[2]=o('<p>The detail screen shows the app name, platform, application IDs, every generated image, and the credential groups the tenant supplied. Credentials are stored encrypted and shown as <strong>Stored</strong> rather than in plain text.</p><h2 id="downloading-the-images" tabindex="-1">Downloading the images <a class="header-anchor" href="#downloading-the-images" aria-label="Permalink to &quot;Downloading the images&quot;">​</a></h2><p>Select <strong>Download images (ZIP)</strong> to get everything in one archive, foldered by platform.</p><ul><li><strong>android/</strong> — a <code>splash/</code> folder with 7 sizes, named by their exact pixels, and a <code>logo/</code> folder.</li><li><strong>ios/</strong> — a <code>splash/</code> folder with 8 sizes, named the same way, and a <code>logo/</code> folder.</li><li><strong>README.txt</strong> — the app name, request reference, tenant, and what each folder holds.</li></ul><p>Each platform folder carries its own copy of the logo, so a build team working on one platform has everything in one place.</p><h2 id="step-1-—-raise-the-build-ticket" tabindex="-1">Step 1 — Raise the build ticket <a class="header-anchor" href="#step-1-—-raise-the-build-ticket" aria-label="Permalink to &quot;Step 1 — Raise the build ticket&quot;">​</a></h2><p>With the request open, select <strong>Raise Ticket</strong>. Add an optional priority and comment, then confirm.</p>',7)),n(s,{src:"/images/managing-app-requests/super-raise-ticket.png",alt:"Raise ticket panel"}),e[3]||(e[3]=o('<p>Confirming creates a ticket in the helpdesk and posts the full build brief to it, with the image archive attached. The panel returns immediately — the ticket is raised in the background, so refresh after a moment to see the number.</p><p>The request moves to <strong>Processing</strong>, and a Helpdesk Ticket card appears on it with a link straight to the ticket and its replies.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The build details — application IDs, and the Apple, Google Play and Firebase credentials — are posted as an <strong>internal note</strong>. Agents can read it on the ticket, but it is never included in the confirmation e-mail sent to the ticket&#39;s contact address.</p></div><h2 id="step-2-—-deliver-the-app" tabindex="-1">Step 2 — Deliver the app <a class="header-anchor" href="#step-2-—-deliver-the-app" aria-label="Permalink to &quot;Step 2 — Deliver the app&quot;">​</a></h2><p>When the team returns the finished build, paste its URL into <strong>Mark as Completed</strong>, with an optional version.</p><p>A request for one platform asks for one URL. A request covering <strong>both</strong> asks for two, because the builds live at different addresses — an <code>.apk</code> or <code>.aab</code> for Android, an App Store link for iOS.</p>',6)),n(s,{src:"/images/managing-app-requests/super-mark-completed.png",alt:"Mark as Completed form"}),e[4]||(e[4]=t("p",null,[a("Saving records the links, moves the request to "),t("strong",null,"Completed"),a(", and e-mails the tenant. Issuing new links disables any earlier ones.")],-1)),e[5]||(e[5]=t("h2",{id:"requesting-a-correction",tabindex:"-1"},[a("Requesting a correction "),t("a",{class:"header-anchor",href:"#requesting-a-correction","aria-label":'Permalink to "Requesting a correction"'},"​")],-1)),e[6]||(e[6]=t("p",null,"If something the tenant submitted is wrong — a logo that reads badly on white, the wrong bundle ID — you do not have to reject the whole request.",-1)),e[7]||(e[7]=t("p",null,[a("Use "),t("strong",null,"Request Correction"),a(" on the field in question and give a reason. The request "),t("strong",null,"stays Pending"),a(" and only that one field reopens for the tenant to edit; everything else remains locked. The tenant is e-mailed with your reason.")],-1)),n(s,{src:"/images/managing-app-requests/super-request-correction.png",alt:"Request correction on a field"}),e[8]||(e[8]=o('<h2 id="rejecting-a-request" tabindex="-1">Rejecting a request <a class="header-anchor" href="#rejecting-a-request" aria-label="Permalink to &quot;Rejecting a request&quot;">​</a></h2><p>If the request cannot go ahead at all, use <strong>Reject</strong> and give a reason. The tenant is e-mailed, and the reason is shown on their copy of the request.</p><p>Rejecting also frees the platform, so the tenant can raise a fresh request for it.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Helpdesk settings live under <strong>Configure → Mobile App Req → UVdesk</strong>.</p>',5)),n(s,{src:"/images/managing-app-requests/super-configuration.png",alt:"Mobile App Request configuration"}),e[9]||(e[9]=o('<ul><li><strong>Enable</strong> — turns ticket raising on. With it off, <strong>Raise Ticket</strong> reports that the helpdesk is disabled.</li><li><strong>Helpdesk URL</strong> — the instance root only, for example <code>https://help.uvdesk.com</code>.</li><li><strong>Access Token</strong> — generated from <strong>UVdesk → Dashboard → Profile → Access Tokens</strong>.</li><li><strong>Ticket Type</strong> — the numeric ticket type id to file under.</li><li><strong>From Name</strong> / <strong>From Email</strong> — who the ticket appears to come from.</li></ul><div class="tip custom-block"><p class="custom-block-title">Set a From Email</p><p>Leave <strong>From Email</strong> blank and tickets are raised from whichever super admin pressed the button, so helpdesk replies land in that person&#39;s personal inbox. Set it to a shared platform address instead — the ticket sender stays consistent no matter who raises it.</p></div><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><ul><li><strong>Pending</strong> — the tenant has submitted. The form is locked, and you can request a correction on individual fields.</li><li><strong>Processing</strong> — the helpdesk ticket has been raised.</li><li><strong>Completed</strong> — the download links are recorded and the tenant has been e-mailed.</li><li><strong>Rejected</strong> — you declined it, with a reason the tenant can read.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every request is scoped to the tenant that raised it. Tenants see only their own requests; the super admin sees them all in one list.</p></div>',5))])}const b=i(p,[["render",g]]);export{k as __pageData,b as default};
